package com.asmj.marketplace.job.service;
import com.asmj.marketplace.job.model.*; import com.asmj.marketplace.job.repository.*; import com.asmj.marketplace.post.model.Post; import com.asmj.marketplace.post.repository.PostRepository; import com.asmj.marketplace.vendor.repository.VendorRepository; import com.asmj.marketplace.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.stereotype.Component; import org.springframework.beans.factory.annotation.Value; import java.time.*; import java.util.*;
@Component @RequiredArgsConstructor public class JobDataSeeder implements CommandLineRunner { final JobListingRepository jobs; final PostRepository posts; final UserRepository users; final VendorRepository vendors; @Value("${app.seed.enabled:true}") boolean enabled;
 public void run(String...x){if(!enabled)return;var u=users.findByEmailIgnoreCase("demo.services@asmj.co.in").orElse(null);if(u==null)return;var v=vendors.findByUserId(u.getId()).orElse(null);if(v==null)return;posts.findAll().stream().filter(p->"JOB".equalsIgnoreCase(p.getType())).forEach(p->{if(jobs.findByPostId(p.getId()).isPresent())return;Map<String,Object>a=p.getAttributes()==null?Map.of():p.getAttributes();jobs.save(JobListing.builder().postId(p.getId()).vendorId(v.getId()).employmentType("FULL_TIME").workMode(String.valueOf(a.getOrDefault("workMode","Hybrid"))).experienceLevel(String.valueOf(a.getOrDefault("experience","2-5 years"))).department("Engineering").education("Bachelor's degree or equivalent").locationText(p.getLocation()!=null?p.getLocation().getCity()+", "+p.getLocation().getState():"Bengaluru, Karnataka").minSalary(p.getPrice()==null?500000:p.getPrice()*0.85).maxSalary(p.getPrice()==null?900000:p.getPrice()).salaryPeriod("year").currency("INR").salaryVisible(true).openings(2).applicationDeadline(Instant.now().plus(Duration.ofDays(45))).skills(List.of("Java","Spring Boot","MongoDB")).benefits(List.of("Health insurance","Paid leave")).screeningQuestions(List.of(JobListing.ScreeningQuestion.builder().id(UUID.randomUUID().toString()).question("How many years of relevant experience do you have?").type("TEXT").required(true).build())).resumeRequired(true).applicationInstructions("Submit your latest resume and complete the screening questions.").createdAt(Instant.now()).updatedAt(Instant.now()).build());}); }
}
